ed by the vendor. Free core scope here is plain-text notes.","website_url":"https://standardnotes.com/","status":"draft"}},{"table":"escape_routes","keys":["slug"],"row":{"id":"c0e7b137-a279-56b0-ac1d-8b2ffdb42c8a","slug":"account-free-note-taking-apps","name":"Account-Free Personal Note-Taking Apps","description":"Compare creating, editing and retaining personal notes locally in installed desktop apps without registering an app account. Downloads, operating-system accounts, sync, sharing and paid services have separate requirements. Official-document review, not hands-on testing or full Notion replacement.","anchor_id":null,"status":"published","editorially_approved":true,"last_verified_at":"2026-11-02T00:00:00Z"},"before":{"id":"c0e7b137-a279-56b0-ac1d-8b2ffdb42c8a","slug":"account-free-note-taking-apps","name":"Account-Free Personal Note-Taking Apps","description":"Compare creating, editing and retaining personal notes locally in installed desktop apps without registering an app account. Downloads, operating-system accounts, sync, sharing and paid services have separate requirements. Official-document review, not hands-on testing or full Notion replacement.","anchor_id":null,"status":"draft","editorially_approved":false,"last_verified_at":"2026-11-02T00:00:00Z"}}],"baselineSources":[{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"bfda8b52-b153-4479-9c04-e46f25e6c7c0","url":"https://obsidian.md/license","title":"License overview - Obsidian","retrievedAt":"2026-10-05T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"bfda8b52-b153-4479-9c04-e46f25e6c7c0","url":"https://obsidian.md/security","title":"Security - Obsidian","retrievedAt":"2026-10-05T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","url":"https://obsidian.md/pricing","title":"obsidian — pricing reference","retrievedAt":"2026-10-06T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","url":"https://obsidian.md/pricing","title":"Obsidian core and optional services","retrievedAt":"2026-10-13T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://obsidian.md/help/Files+and+folders/Manage+vaults","title":"Obsidian local vault creation","retrievedAt":"2026-10-13T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://obsidian.md/help/Getting+started/Create+your+first+note","title":"Obsidian first text note","retrievedAt":"2026-10-13T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://obsidian.md/pricing","title":"obsidian — tradeoff reference","retrievedAt":"2026-10-06T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://obsidian.md/pricing","title":"Obsidian core and optional services","retrievedAt":"2026-10-13T08:00:00+08:00"},{"product_id":"46d1c057-ff54-4843-a96e-fb1748f0ac49","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://www.notion.com/help/create-your-first-page","title":"Notion: create a page","retrievedAt":"2026-10-13T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"bfda8b52-b153-4479-9c04-e46f25e6c7c0","url":"https://affine.pro/download","title":"Download for Offline Notes and Whiteboards - AFFiNE","retrievedAt":"2026-10-05T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","url":"https://affine.pro/pricing","title":"AFFiNE — AI source review reference","retrievedAt":"2026-10-06T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"83353c3f-3cd2-4505-8311-f722e720867c","url":"https://affine.pro/pricing","title":"AFFiNE local and Cloud plans","retrievedAt":"2026-10-08T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://affine.pro/blog/import-your-data-from-notion-into-affine","title":"AFFiNE Notion import guide","retrievedAt":"2026-10-08T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://affine.pro/download","title":"AFFiNE — AI source review reference","retrievedAt":"2026-10-06T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://affine.pro/download","title":"AFFiNE native local-first download","retrievedAt":"2026-10-08T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://affine.pro/pricing","title":"AFFiNE — AI source review reference","retrievedAt":"2026-10-06T08:00:00+08:00"},{"product_id":"188f3374-5440-47ba-81ad-ed0a5a74f9b5","attribute_id":"18dee1eb-8a8a-45fa-b463-8487065642d9","url":"https://affine.pro/pricing","title":"AFFiNE local and Cloud plans","retrievedAt":"2026-10-08T08:00:00+08:00"}]}$payload$::jsonb; op jsonb; expected jsonb; actual jsonb; t text; cols text; keys_sql text; match_sql text; found boolean; same boolean; sn_status text; route_status text; approved boolean;
BEGIN
 PERFORM set_config('lock_timeout','5s',true);
 PERFORM pg_advisory_xact_lock(hashtext('software_discovery.issue21.account_free_draft'));
 LOCK TABLE software_discovery.products,software_discovery.attributes,software_discovery.product_attributes,software_discovery.escape_routes,software_discovery.escape_route_products,software_discovery.evidence_sources,software_discovery.claim_evidence,software_discovery.product_attribute_evidence IN SHARE ROW EXCLUSIVE MODE;
 IF NOT EXISTS(SELECT FROM pg_proc WHERE oid=to_regprocedure('software_discovery.ingest_discovery_events_v2(jsonb,text)') AND md5(replace(prosrc,E'\r',''))='b93b7d7cfab49a2a033b808b62b3fb26') THEN RAISE EXCEPTION 'Issue21 analytics patch must be applied first'; END IF;
 SELECT status INTO sn_status FROM software_discovery.products WHERE id=(data->>'snId')::uuid;
 SELECT status,editorially_approved INTO route_status,approved FROM software_discovery.escape_routes WHERE id=(data->>'routeId')::uuid;
 IF NOT ((sn_status='draft' AND route_status='draft' AND NOT approved) OR (sn_status='published' AND route_status='published' AND approved)) THEN RAISE EXCEPTION 'Issue21 inconsistent publication state'; END IF;

 FOR expected IN SELECT value FROM jsonb_array_elements(data->'guardProducts') LOOP
  SELECT to_jsonb(p)-'created_at'-'updated_at' INTO actual FROM software_discovery.products p WHERE p.id=(expected->>'id')::uuid;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Issue21 original product metadata drift'; END IF;
 END LOOP;
 FOR expected IN SELECT value FROM jsonb_array_elements(data->'guardTaxonomy') LOOP
  SELECT to_jsonb(a)-'created_at'-'updated_at' INTO actual FROM software_discovery.attributes a WHERE a.id=(expected->>'id')::uuid;
  IF actual IS DISTINCT FROM expected THEN RAISE EXCEPTION 'Issue21 taxonomy baseline drift'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM software_discovery.product_attributes WHERE product_id IN (SELECT (v->>'id')::uuid FROM jsonb_array_elements(data->'guardProducts') v) AND attribute_id<>(data->>'scopeId')::uuid)<>jsonb_array_length(data->'guardAttributes') THEN RAISE EXCEPTION 'Issue21 old attribute count drift'; END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements(data->'guardAttributes') LOOP
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO match_sql FROM jsonb_object_keys(expected) x(key);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.product_attributes target CROSS JOIN jsonb_populate_record(NULL::software_discovery.product_attributes,$1) source WHERE %s)',match_sql) INTO same USING expected;
  IF NOT same THEN RAISE EXCEPTION 'Issue21 old claim drift'; END IF;
 END LOOP;
 IF (SELECT count(*) FROM software_discovery.product_attributes WHERE product_id=(data->>'snId')::uuid)<>4 OR (SELECT count(*) FROM software_discovery.escape_route_products WHERE escape_route_id=(data->>'routeId')::uuid)<>3 THEN RAISE EXCEPTION 'Issue21 draft graph changed'; END IF;
 FOR op IN SELECT value FROM jsonb_array_elements(data->'ops') LOOP
  t=op->>'table';expected=op->'row';
  IF t='products' THEN expected=jsonb_set(expected,'{status}',to_jsonb(sn_status)); END IF;
  IF t='escape_routes' THEN expected=jsonb_set(jsonb_set(expected,'{status}',to_jsonb(route_status)),'{editorially_approved}',to_jsonb(approved)); END IF;
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND ') INTO match_sql FROM jsonb_object_keys(expected) x(key);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s)',t,t,match_sql) INTO same USING expected;
  IF NOT same THEN RAISE EXCEPTION 'Issue21 accepted draft row drift in %',t; END IF;
 END LOOP;
 IF EXISTS(SELECT FROM software_discovery.product_anchors WHERE product_id=(data->>'snId')::uuid) OR EXISTS(SELECT FROM software_discovery.product_audiences WHERE product_id=(data->>'snId')::uuid) OR EXISTS(SELECT FROM software_discovery.product_problems WHERE product_id=(data->>'snId')::uuid) OR (SELECT count(*) FROM software_discovery.escape_route_products WHERE product_id=(data->>'snId')::uuid)<>1 OR (SELECT count(*) FROM software_discovery.product_attribute_evidence WHERE product_id=(data->>'snId')::uuid)<>6 THEN RAISE EXCEPTION 'Issue21 Standard Notes graph/provenance changed'; END IF;
 FOR expected IN SELECT value FROM jsonb_array_elements(data->'baselineSources') LOOP
  IF NOT EXISTS(SELECT FROM software_discovery.product_attribute_evidence l JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources s ON s.id=e.evidence_source_id WHERE l.product_id=(expected->>'product_id')::uuid AND l.attribute_id=(expected->>'attribute_id')::uuid AND s.title=expected->>'title' AND s.url IS NOT DISTINCT FROM expected->>'url' AND s.retrieved_at IS NOT DISTINCT FROM (expected->>'retrievedAt')::timestamptz) THEN RAISE EXCEPTION 'Issue21 historical claim provenance drift'; END IF;
 END LOOP;
 -- Only two reviewed new scope claims and their new provenance may be inserted/removed.
 FOR op IN SELECT value FROM jsonb_array_elements(data->'added')  LOOP
  t=op->>'table';expected=op->'row';
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',value,value),' AND ') INTO keys_sql FROM jsonb_array_elements_text(op->'keys');
  SELECT string_agg(format('target.%I IS NOT DISTINCT FROM source.%I',key,key),' AND '),string_agg(format('%I',key),',') INTO match_sql,cols FROM jsonb_object_keys(expected) x(key);
  EXECUTE format('SELECT EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s),EXISTS(SELECT 1 FROM software_discovery.%I target CROSS JOIN jsonb_populate_record(NULL::software_discovery.%I,$1) source WHERE %s AND %s)',t,t,keys_sql,t,t,keys_sql,match_sql) INTO found,same USING expected;
  IF found AND NOT same OR sn_status='published' AND NOT found THEN RAISE EXCEPTION 'Issue21 scope/provenance drift in %',t; END IF;
  IF NOT found THEN EXECUTE format('INSERT INTO software_discovery.%I (%s) SELECT %s FROM jsonb_populate_record(NULL::software_discovery.%I,$1)',t,cols,cols,t) USING expected; END IF;
 END LOOP;
IF sn_status='draft' THEN
  UPDATE software_discovery.products SET status='published' WHERE id=(data->>'snId')::uuid;
  UPDATE software_discovery.escape_routes SET status='published',editorially_approved=true WHERE id=(data->>'routeId')::uuid;
 END IF;
 IF (SELECT count(*) FROM software_discovery.products p JOIN software_discovery.escape_route_products m ON m.product_id=p.id WHERE m.escape_route_id='c0e7b137-a279-56b0-ac1d-8b2ffdb42c8a' AND p.status='published' AND NOT EXISTS(SELECT FROM (VALUES ('no-account-required'),('account-free-note-workflow-scope'),('pricing-model'),('trade-off-summary')) required(slug) WHERE NOT EXISTS(SELECT FROM software_discovery.product_attributes c JOIN software_discovery.attributes a ON a.id=c.attribute_id WHERE c.product_id=p.id AND a.slug=required.slug AND c.verification_status='verified' AND c.confidence BETWEEN .8 AND 1 AND c.last_verified_at IS NOT NULL AND (CASE a.slug WHEN 'no-account-required' THEN c.value_boolean IS TRUE WHEN 'account-free-note-workflow-scope' THEN c.value_text='personal-desktop-local-note-creation-editing-retention-without-app-account' ELSE length(trim(c.value_text))>0 END) AND EXISTS(SELECT FROM software_discovery.product_attribute_evidence l JOIN software_discovery.claim_evidence e ON e.id=l.claim_evidence_id JOIN software_discovery.evidence_sources s ON s.id=e.evidence_source_id WHERE l.product_id=c.product_id AND l.attribute_id=c.attribute_id AND s.url ~ '^https?://[^/?#@:]+(:[0-9]+)?([/?#]|$)'))))<>3 THEN RAISE EXCEPTION 'Issue21 needs three source-backed qualified published products'; END IF;
RAISE NOTICE 'Issue21 apply complete';

END $release$;
